// SPDX-License-Identifier: GPL-3.0-or-later
//! Direct verification of all 20 `HELM`, `PC`, `Skye`, and blend EOS component
//! test points against compiled upstream Fortran MESA release `26.4.1` (`r26.4.1`,
//! MESA SDK `x86_64-linux-26.6.1`, `GCC 15.2.0`, `CRMATH`), parsed from
//! `benchmarks/fortran_mesa/eos_oracles/mesa_26_4_1_eos_oracles.tsv`
//! (generated by `benchmarks/fortran_mesa/eos_oracles/gen_eos_oracles.f90`,
//! `#161`, `T2-15`).

mod common;

use flexmesa_chem::{NuclideCatalog, get_composition_info};
use flexmesa_eos::{
    EosConfig, HelmTable, PcConfig, SkyeConfig, SkyeSolidMixingRule,
    eos_dt_get, eval_pc_eos, eval_skye_eos,
};
use flexmesa_math::exp10;

fn make_comp(
    he_frac: f64,
    carbon_frac: f64,
    oxygen_frac: f64,
) -> (Vec<usize>, Vec<f64>, f64, f64) {
    let cat = NuclideCatalog::builtin();
    let chem_id = ["h1", "he4", "c12", "n14", "o16", "ne20", "mg24"]
        .into_iter()
        .map(|n| cat.get_by_name(n).unwrap().chem_id)
        .collect::<Vec<_>>();
    let xa = vec![0.0, he_frac, carbon_frac, 0.0, oxygen_frac, 0.0, 0.0];
    let comp = get_composition_info(&cat, &chem_id, &xa, true).unwrap();
    (chem_id, xa, comp.abar, comp.zbar)
}

fn run_skye_and_blend_suite() {
    let ht = HelmTable::builtin().expect("builtin HELM table");
    let comps = [make_comp(0.0, 1.0, 0.0), make_comp(0.0, 0.5, 0.5)];
    let skye_cases = [
        (
            "skye_c12_liq",
            0,
            1.0e6,
            1.0e8,
            false,
            SkyeSolidMixingRule::Ogata,
            5.0e-12,
        ),
        (
            "skye_c12_liq_ion",
            0,
            1.0e6,
            1.0e8,
            true,
            SkyeSolidMixingRule::Ogata,
            5.0e-12,
        ),
        (
            "skye_co_liq",
            1,
            1.0e6,
            1.0e7,
            false,
            SkyeSolidMixingRule::Ogata,
            5.0e-11,
        ),
        (
            "skye_co_sol_ogata",
            1,
            1.0e6,
            2.0e6,
            false,
            SkyeSolidMixingRule::Ogata,
            5.0e-8,
        ),
        (
            "skye_co_sol_pc",
            1,
            1.0e6,
            2.0e6,
            false,
            SkyeSolidMixingRule::Pc,
            5.0e-8,
        ),
        (
            "skye_c12_phase",
            0,
            1.0e6,
            2.65e6,
            false,
            SkyeSolidMixingRule::Ogata,
            5.0e-8,
        ),
    ];
    for (cid, c_idx, rho, temp, ion, rule, tol) in skye_cases {
        let (chem_id, xa, abar, zbar) = &comps[c_idx];
        let cfg = SkyeConfig {
            skye_use_ion_offsets: ion,
            skye_solid_mixing_rule: rule,
            ..SkyeConfig::default()
        };
        let out = eval_skye_eos(&cfg, ht, rho, temp, *abar, *zbar, chem_id, xa)
            .expect(cid);
        common::assert_eos_against_mesa(
            cid,
            &out,
            tol,
            tol,
            &[],
            false,
        );
    }

    let (cid_c, xa_c, _, _) = &comps[0];
    let mut cfg_sk_bl = EosConfig {
        use_skye: true,
        use_pc: false,
        use_free_eos: false,
        use_opal_scvh: false,
        ..EosConfig::default()
    };
    cfg_sk_bl.skye.skye_use_ion_offsets = false;
    let out =
        eos_dt_get(ht, exp10(3.45), 1.0e7, cid_c, xa_c, &cfg_sk_bl).unwrap();
    common::assert_eos_against_mesa(
        "eosdt_skye_helm_blend",
        &out,
        1.0e-7,
        1.0e-7,
        &[],
        false,
    );
}

#[test]
fn test_oracle_header_records_mesa_26_4_1_provenance() {
    let tsv = common::EOS_ORACLES_TSV;
    assert!(tsv.contains("# mesa_version_number=r26.4.1"));
    assert!(tsv.contains("# mesa_git_tag=26.4.1"));
    assert!(tsv.contains(
        "# mesa_git_commit=c8c202662922a22b3efefa824473ad615c623afd"
    ));
    assert!(tsv.contains("# mesasdk_version=x86_64-linux-26.6.1"));
    assert!(tsv.contains("# math_backend=CRMATH"));
    assert!(tsv.contains("# compiler=GCC version 15.2.0"));
}

#[test]
fn test_all_five_helm_cases_against_compiled_mesa_26_4_1() {
    let cases = [
        ("pure_he_2e8_100", 2.0e8, 100.0, 4.0, 2.0),
        ("pure_h_2e8_100", 2.0e8, 100.0, 1.0, 1.0),
        (
            "solar_2e8_100",
            2.0e8,
            100.0,
            1.296_635_341_025_522_2,
            1.102_140_039_871_693_8,
        ),
        (
            "test_components",
            1.0e6,
            exp10(3.5),
            2.990_964_711_670_598,
            1.674_940_238_535_534_8,
        ),
        ("sample_eos_c12", 1.0e9, 1.0e4, 12.0, 6.0),
    ];
    for (case_id, temp, den, abar, zbar) in cases {
        common::assert_helm_against_mesa(
            case_id, temp, den, abar, zbar, 1.0e-13,
        );
    }
}

#[test]
fn test_all_fifteen_pc_skye_and_blend_cases_against_compiled_mesa_26_4_1() {
    let ht = HelmTable::builtin().expect("builtin HELM table");
    let pc_cfg = PcConfig::default();
    let comps = [
        make_comp(0.0, 1.0, 0.0),
        make_comp(0.0, 0.5, 0.5),
        make_comp(1.0, 0.0, 0.0),
    ];
    let pc_cases = [
        ("pc_c12_liq", 0, 1.0e6, 1.0e8),
        ("pc_co_liq", 1, 1.0e6, 1.0e7),
        ("pc_c12_trans_eosfi", 0, 1.0e6, 3.1e6),
        ("pc_c12_trans_phase", 0, 1.0e6, 2.05e6),
        ("pc_c12_sol", 0, 1.0e6, 1.0e6),
        ("pc_co_sol", 1, 1.0e6, 1.0e6),
        ("pc_he4_qmelt", 2, 1.0e8, 1.0e5),
    ];
    for (cid, c_idx, rho, temp) in pc_cases {
        let (chem_id, xa, abar, zbar) = &comps[c_idx];
        let out = eval_pc_eos(&pc_cfg, rho, temp, *abar, *zbar, chem_id, xa)
            .expect(cid);
        common::assert_eos_against_mesa(
            cid,
            &out,
            1.0e-11,
            5.0e-9,
            &[],
            false,
        );
    }

    let (cid_c, xa_c, _, _) = &comps[0];
    let mut cfg_pc_bl = EosConfig {
        use_skye: false,
        use_pc: true,
        use_free_eos: false,
        use_opal_scvh: false,
        ..EosConfig::default()
    };
    cfg_pc_bl.pc.pc_use_gamma_limit_instead_of_t = true;
    let out = eos_dt_get(ht, exp10(2.9), exp10(6.5), cid_c, xa_c, &cfg_pc_bl)
        .unwrap();
    common::assert_eos_against_mesa(
        "eosdt_pc_helm_blend",
        &out,
        1.0e-11,
        5.0e-9,
        &[],
        false,
    );

    run_skye_and_blend_suite();
}

#[test]
fn test_helm_ideal_edge_blend_matches_mesa_26_4_1_swapped_alfa_partials() {
    let ht = HelmTable::builtin().expect("builtin HELM table");
    let (cid_c, xa_c, _, _) = make_comp(0.0, 1.0, 0.0);
    let cfg_hi_rho = EosConfig {
        use_cms: false,
        use_skye: false,
        use_pc: false,
        use_free_eos: false,
        use_opal_scvh: false,
        ..EosConfig::default()
    };
    let out_hi_rho =
        eos_dt_get(ht, exp10(15.05), exp10(12.5), &cid_c, &xa_c, &cfg_hi_rho)
            .expect("high-density HELM/ideal blend");
    common::assert_eos_against_mesa(
        "eosdt_helm_ideal_hi_rho_blend",
        &out_hi_rho,
        1.0e-12,
        1.0e-12,
        &[],
        false,
    );

    let cat = NuclideCatalog::builtin();
    let cid_sol = ["h1", "he4", "c12", "n14", "o16", "ne20", "mg24"]
        .into_iter()
        .map(|n| cat.get_by_name(n).unwrap().chem_id)
        .collect::<Vec<_>>();
    let mut xa_sol = vec![
        0.70,
        0.28,
        0.02 * 0.173_312,
        0.02 * 0.053_177,
        0.02 * 0.482_398,
        0.02 * 0.098_675,
        0.0,
    ];
    let sum6: f64 = xa_sol[..6].iter().sum();
    xa_sol[6] = 1.0 - sum6;

    let mut cfg_lo_t = cfg_hi_rho;
    cfg_lo_t.helm.include_elec_pos = false;
    let out_lo_t =
        eos_dt_get(ht, 1.0e-8, exp10(2.95), &cid_sol, &xa_sol, &cfg_lo_t)
            .expect("low-temperature include_elec_pos=false HELM/ideal blend");
    common::assert_eos_against_mesa(
        "eosdt_helm_ideal_lo_t_noep_blend",
        &out_lo_t,
        1.0e-10,
        1.0e-8,
        &[],
        false,
    );
}
